WITH cleaned AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, CONCAT(device_code, ' - ', firmware) AS device_code_firmware, LOWER(firmware) AS firmware_lower FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 08:00:00'), cleaned_device_readings AS (SELECT id, reading_ts, temp_c, humidity, firmware, device_code_firmware, FLOOR(humidity) AS humidity_whole FROM cleaned WHERE firmware IN ('1.0.3', '1.1.0', '2.0.1')), filtered AS (SELECT *, CASE WHEN humidity_whole >= 80 THEN 'High' WHEN humidity_whole >= 34 THEN 'Medium' ELSE 'Low' END AS humidity_whole_band FROM cleaned_device_readings WHERE humidity_whole >= 44) SELECT id, device_code_firmware, humidity_whole, humidity_whole_band FROM filtered
